module nnc_chk_flow #(
  parameter int PARA_SPI_CLK_DIV = 4
) (
  input  logic                        i_clk,
  input  logic                        i_rst_n,
  input  logic                        i_cmd_valid,
  input  logic                        o_cmd_ready,
  input  logic [7:0]                  i_cmd_data,
  input  logic                        i_cmd_last,
  input  logic                        o_rsp_valid,
  input  logic                        i_rsp_ready,
  input  logic [7:0]                  o_rsp_data,
  input  logic                        o_sclk,
  input  logic                        o_mosi,
  input  logic                        i_miso,
  input  logic                        o_cs_n,
  input  logic                        i_cpol,
  input  logic                        i_cpha
);

  int unsigned fails_CHK_010 = 0;
  int unsigned hits_CHK_010 = 0;

  localparam int unsigned XFER_CYC = 16 * PARA_SPI_CLK_DIV;

  logic        flow_hs;
  logic        flow_busy;
  logic        flow_last_q;
  logic        flow_pause;
  logic        flow_pause_q;
  int unsigned flow_cnt;
  // NNC verification fix (fix-verif, triage B): CPOL_b = i_cpol captured at the first acceptance edge of the
  // burst (REQ-MODE-001, term CPOL_b). REQ-FLOW-003 requires o_sclk = CPOL_b in Pause, not the current i_cpol,
  // which may differ during the ENV-003 error test (REQ-MODE-003, REQ-ERR-001).
  logic        flow_cpol_b;

  assign flow_hs = i_cmd_valid && o_cmd_ready;

  always_ff @(posedge i_clk) begin
    if (!i_rst_n) begin
      flow_busy    <= 1'b0;
      flow_last_q  <= 1'b0;
      flow_pause   <= 1'b0;
      flow_pause_q <= 1'b0;
      flow_cnt     <= 0;
      flow_cpol_b  <= 1'b0;
    end else begin
      flow_pause_q <= flow_pause;
      // NNC verification fix (fix-verif, triage B): burst start = handshake with o_cs_n=1 in the cycle ending at
      // the acceptance edge; capture CPOL_b there (REQ-MODE-001).
      if (flow_hs && o_cs_n) flow_cpol_b <= i_cpol;
      if (flow_hs) begin
        flow_busy   <= 1'b1;
        flow_cnt    <= 0;
        flow_last_q <= i_cmd_last;
        flow_pause  <= 1'b0;
      end else if (flow_busy) begin
        if (flow_cnt == XFER_CYC - 1) begin
          flow_busy <= 1'b0;
          if (!flow_last_q) flow_pause <= 1'b1;
        end else begin
          flow_cnt <= flow_cnt + 1;
        end
      end
    end
  end

  // CHK-010: Pause entry and Pause outputs (SPI-7.8-02, SPI-7.8-03, SPI-3-05, SPI-1.2-08, SPI-14-20, SPI-8-13)
  // NNC verification fix (fix-verif, triage B): o_sclk compared with the captured CPOL_b (REQ-FLOW-003,
  // contract CHK-010 "o_sclk=CPOL_b") instead of the current i_cpol input.
  a_CHK_010: assert property (@(posedge i_clk) disable iff (!i_rst_n)
    flow_pause |-> ((o_cs_n == 1'b0) && (o_sclk == flow_cpol_b) &&
                    (!flow_pause_q || ($stable(o_sclk) && $stable(o_mosi)))))
    else begin fails_CHK_010++; $display("NNC_FAIL CHK-010 @%0t", $time); end
  always_ff @(posedge i_clk) if (!(!i_rst_n) && (flow_pause)) hits_CHK_010 <= hits_CHK_010 + 1;

  final begin
    $display("NNC_CHECK CHK-010 hits=%0d fails=%0d", hits_CHK_010, fails_CHK_010);
  end
endmodule

module nnc_chk_reset #(
  parameter int PARA_SPI_CLK_DIV = 4
) (
  input  logic                        i_clk,
  input  logic                        i_rst_n,
  input  logic                        i_cmd_valid,
  input  logic                        o_cmd_ready,
  input  logic [7:0]                  i_cmd_data,
  input  logic                        i_cmd_last,
  input  logic                        o_rsp_valid,
  input  logic                        i_rsp_ready,
  input  logic [7:0]                  o_rsp_data,
  input  logic                        o_sclk,
  input  logic                        o_mosi,
  input  logic                        i_miso,
  input  logic                        o_cs_n,
  input  logic                        i_cpol,
  input  logic                        i_cpha
);

  int unsigned fails_CHK_015 = 0;
  int unsigned hits_CHK_015 = 0;
  int unsigned fails_CHK_016 = 0;
  int unsigned hits_CHK_016 = 0;
  int unsigned fails_CHK_017 = 0;
  int unsigned hits_CHK_017 = 0;
  int unsigned fails_CHK_018 = 0;
  int unsigned hits_CHK_018 = 0;

  // helper state
  logic chk15_armed = 1'b0;
  logic rst_q       = 1'b0;
  logic wait_hs     = 1'b0;

  always @(negedge i_rst_n) chk15_armed = 1'b1;
  always @(posedge i_rst_n) chk15_armed = 1'b0;

  always_ff @(posedge i_clk) begin
    rst_q <= !i_rst_n;
    if (!i_rst_n) wait_hs <= 1'b1;
    else if (i_cmd_valid && o_cmd_ready) wait_hs <= 1'b0;
  end

  // NNC verification fix (fix-verif, triage B): the action block of a deferred assertion must be a single
  // subroutine call, so the fail counting and reporting moved into this function (same counter, same message).
  function automatic void chk15_fail();
    fails_CHK_015++;
    $display("NNC_FAIL CHK-015 @%0t", $time);
  endfunction

  // CHK-015: Outputs take reset values at once on i_rst_n assertion (SPI-6.2-01, SPI-10-09, SPI-10-11)
  // NNC verification fix (fix-verif, triage B): deferred immediate assertion (assert final). The contract
  // (CHK-015) checks "in the same time step (after combinational settling)". A plain immediate assertion counted
  // a fail on the first, unsettled evaluation inside the time step of the 1->0 transition. A deferred
  // assertion is flushed and re-evaluated each time this block re-triggers in the time step, so only the
  // settled values of that time step are judged. The full output list and the exact values are unchanged,
  // and the check stays active from the assertion until i_rst_n is released, so it also holds before the
  // next rising edge.
  always @(chk15_armed or i_rst_n or o_cs_n or o_mosi or o_rsp_valid or o_rsp_data or o_cmd_ready or o_sclk or i_cpol) begin
    if (chk15_armed && !i_rst_n) begin
      a_CHK_015: assert final (o_cs_n === 1'b1 && o_mosi === 1'b0 && o_rsp_valid === 1'b0 &&
                               o_rsp_data === 8'h00 && o_cmd_ready === 1'b1 && o_sclk === i_cpol)
        else chk15_fail();
    end
  end
  always_ff @(posedge i_clk) if (!i_rst_n) hits_CHK_015 <= hits_CHK_015 + 1;

  // CHK-016: Output values held while in reset (SPI-6.2-02, SPI-6.2-04, SPI-6.2-05, SPI-6.2-06, SPI-5-04, SPI-5-08, SPI-5-10, SPI-5-12, SPI-5-13, SPI-6.2-07, SPI-14-12)
  always @(posedge i_clk or negedge i_clk) begin
    if (!i_rst_n) begin
      a_CHK_016: assert (o_cs_n === 1'b1 && o_mosi === 1'b0 && o_rsp_valid === 1'b0 &&
                         o_rsp_data === 8'h00 && o_cmd_ready === 1'b1)
        else begin fails_CHK_016++; $display("NNC_FAIL CHK-016 @%0t", $time); end
    end
  end
  always_ff @(posedge i_clk) if (!i_rst_n) hits_CHK_016 <= hits_CHK_016 + 1;

  // CHK-017: o_sclk follows i_cpol combinationally during reset (SPI-6.2-03, SPI-5-11)
  always @(posedge i_clk or negedge i_clk or i_cpol or o_sclk) begin
    if (!i_rst_n) begin
      a_CHK_017: assert (o_sclk === i_cpol)
        else begin fails_CHK_017++; $display("NNC_FAIL CHK-017 @%0t", $time); end
    end
  end
  always_ff @(posedge i_clk) if (!i_rst_n) hits_CHK_017 <= hits_CHK_017 + 1;

  // CHK-018: Ready to accept at first edge after reset release (SPI-6.2-11, SPI-7.1-08, SPI-14-21, SPI-6.2-12)
  a_CHK_018: assert property (@(posedge i_clk) disable iff (!i_rst_n)
    wait_hs |-> (o_cmd_ready && (!rst_q || (o_cs_n && !o_rsp_valid))))
    else begin fails_CHK_018++; $display("NNC_FAIL CHK-018 @%0t", $time); end
  always_ff @(posedge i_clk) if (!(!i_rst_n) && (wait_hs)) hits_CHK_018 <= hits_CHK_018 + 1;

  final begin
    $display("NNC_CHECK CHK-015 hits=%0d fails=%0d", hits_CHK_015, fails_CHK_015);
    $display("NNC_CHECK CHK-016 hits=%0d fails=%0d", hits_CHK_016, fails_CHK_016);
    $display("NNC_CHECK CHK-017 hits=%0d fails=%0d", hits_CHK_017, fails_CHK_017);
    $display("NNC_CHECK CHK-018 hits=%0d fails=%0d", hits_CHK_018, fails_CHK_018);
  end
endmodule
